use crate::inference::Inference;
use crate::model_io::PretrainedModel;
use serde::Deserialize;
use serde_json::json;
use std::io::{Read,Write};
use std::net::{TcpListener,TcpStream};
use std::sync::{Arc,Mutex};
use std::time::{SystemTime,UNIX_EPOCH};
const HTML:&str=r#"<!doctype html><html><head><meta charset=utf-8><meta name=viewport content='width=device-width,initial-scale=1'><title>SmaulNative</title><style>body{margin:0;background:#101010;color:#eee;font:15px system-ui;display:flex;height:100vh}main{max-width:850px;width:100%;margin:auto;padding:24px;box-sizing:border-box}#chat{height:75vh;overflow:auto}.m{margin:20px 0;white-space:pre-wrap;line-height:1.6}.u{background:#222;padding:12px;border-radius:12px}.a{padding:12px}textarea{width:100%;box-sizing:border-box;background:#181818;color:#eee;border:1px solid #333;border-radius:12px;padding:12px;resize:none}button{margin-top:8px;padding:10px 18px;border:0;border-radius:9px;cursor:pointer}</style></head><body><main><h2>SmaulNative</h2><div id=chat></div><textarea id=i rows=3 placeholder='Message SmaulNative'></textarea><button onclick=send()>Send</button><script>let m=[];function draw(){chat.innerHTML=m.map(x=>`<div class=m><b>${x.role}</b><div class=${x.role==='You'?'u':'a'}>${x.text.replaceAll('&','&amp;').replaceAll('<','&lt;')}</div></div>`).join('');chat.scrollTop=chat.scrollHeight}async function send(){let x=i.value.trim();if(!x)return;i.value='';m.push({role:'You',text:x},{role:'SmaulNative',text:''});draw();let r=await fetch('/v1/chat/completions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({messages:[...m.slice(0,-1)].map(x=>({role:x.role==='You'?'user':'assistant',content:x.text})),stream:false,max_tokens:256,temperature:.7,top_p:.95})});let j=await r.json();m[m.length-1].text=j.choices?.[0]?.message?.content||j.error||'';draw()}i.addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();send()}})</script></main></body></html>"#;
#[derive(Deserialize)]struct Message{role:String,content:String}
#[derive(Deserialize)]struct Chat{messages:Vec<Message>,#[serde(default="dmax")]max_tokens:usize,#[serde(default="dtemp")]temperature:f32,#[serde(default="dp")]top_p:f32,#[serde(default)]top_k:usize,#[serde(default="drp")]repetition_penalty:f32,#[serde(default)]stream:bool,system:Option<String>}
fn dmax()->usize{256}fn dtemp()->f32{0.7}fn dp()->f32{0.95}fn drp()->f32{1.05}
pub struct Server{pub model:Arc<Mutex<PretrainedModel>>,pub max_prompt_tokens:usize}
impl Server{pub fn new(model_dir:impl AsRef<std::path::Path>,max_prompt_tokens:usize)->Result<Self,String>{Ok(Self{model:Arc::new(Mutex::new(PretrainedModel::load(model_dir)?)),max_prompt_tokens})}pub fn serve(&self,host:&str,port:u16)->Result<(),String>{let listener=TcpListener::bind((host,port)).map_err(|e|e.to_string())?;println!("SmaulNative listening on http://{host}:{port}");for stream in listener.incoming(){match stream{Ok(s)=>{let model=Arc::clone(&self.model);let max=self.max_prompt_tokens;std::thread::spawn(move||{if let Err(e)=handle(s,model,max){eprintln!("server: {e}")}});},Err(e)=>eprintln!("accept: {e}")}}Ok(())}}
fn response(stream:&mut TcpStream,status:&str,typ:&str,body:&str){let _=write!(stream,"HTTP/1.1 {status}\r\nContent-Type: {typ}\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{body}",body.as_bytes().len());}
fn handle(mut stream:TcpStream,model:Arc<Mutex<PretrainedModel>>,max_prompt:usize)->Result<(),String>{let mut buf=Vec::new();let mut tmp=[0u8;8192];let header_end;loop{let n=stream.read(&mut tmp).map_err(|e|e.to_string())?;if n==0{return Ok(())}buf.extend_from_slice(&tmp[..n]);if let Some(p)=buf.windows(4).position(|x|x==b"\r\n\r\n"){header_end=p+4;break}if buf.len()>1024*1024{return Err("request headers too large".into())}}let headers=String::from_utf8_lossy(&buf[..header_end]);let mut it=headers.lines();let first=it.next().unwrap_or("");let mut parts=first.split_whitespace();let method=parts.next().unwrap_or("");let path=parts.next().unwrap_or("");let len=it.find_map(|x|{let mut p=x.splitn(2,':');if p.next()?.eq_ignore_ascii_case("content-length"){p.next()?.trim().parse().ok()}else{None}}).unwrap_or(0);while buf.len()<header_end+len{let n=stream.read(&mut tmp).map_err(|e|e.to_string())?;if n==0{break}buf.extend_from_slice(&tmp[..n]);}if method=="GET"&&path=="/"{response(&mut stream,"200 OK","text/html; charset=utf-8",HTML);return Ok(())}if method=="GET"&&path=="/health"{let m=model.lock().map_err(|_|"model lock poisoned".to_string())?;let body=json!({"status":"ok","device":"cpu","parameters":format!("{:.1}M",m.model.parameter_count()as f32/1e6)}).to_string();response(&mut stream,"200 OK","application/json",&body);return Ok(())}if method=="GET"&&path=="/v1/models"{let body=json!({"object":"list","data":[{"id":"rwkv-x","object":"model","owned_by":"SmaulNative"}]}).to_string();response(&mut stream,"200 OK","application/json",&body);return Ok(())}if method!="POST"||path!="/v1/chat/completions"{response(&mut stream,"404 Not Found","application/json","{\"error\":\"not found\"}");return Ok(())}let body=&buf[header_end..header_end+len.min(buf.len()-header_end)];let req:Chat=serde_json::from_slice(body).map_err(|e|e.to_string())?;let mut m=model.lock().map_err(|_|"model lock poisoned".to_string())?;let engine=Inference{model:&m.model,tokenizer:&m.tokenizer,eos_id:m.tokenizer.eos_id()};let messages:Vec<(&str,&str)>=req.messages.iter().map(|x|(x.role.as_str(),x.content.as_str())).collect();let prompt=engine.chat_prompt(&messages,req.system.as_deref().or(Some("You are SmaulNative, a helpful local AI assistant.")));let count=engine.tokenizer.encode(&prompt).len();if count>max_prompt{response(&mut stream,"413 Payload Too Large","application/json",&json!({"error":format!("prompt exceeds {max_prompt} tokens ({count})")}).to_string());return Ok(())}let created=SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_secs();let text=engine.generate(&prompt,req.max_tokens,req.temperature,req.top_k,req.top_p,req.repetition_penalty,created);let id=format!("chatcmpl-{created}");if req.stream{let mut out=String::new();out.push_str(&format!("data: {}\n\n",json!({"id":id,"object":"chat.completion.chunk","created":created,"model":"rwkv-x","choices":[{"index":0,"delta":{"content":text},"finish_reason":null}]})));out.push_str(&format!("data: {}\n\ndata: [DONE]\n\n",json!({"id":id,"object":"chat.completion.chunk","created":created,"model":"rwkv-x","choices":[{"index":0,"delta":{},"finish_reason":"stop"}]})));response(&mut stream,"200 OK","text/event-stream; charset=utf-8",&out)}else{response(&mut stream,"200 OK","application/json",&json!({"id":id,"object":"chat.completion","created":created,"model":"rwkv-x","choices":[{"index":0,"message":{"role":"assistant","content":text},"finish_reason":"stop"}]}).to_string())}Ok(())}
